using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Windows;
using System.Windows.Controls;
namespace FlowShift {
public static class WheelPresets {
 public static readonly string[] Categories={"Image","Pdf","Document","Spreadsheet","Presentation","Video","Audio","Archive","Ebook","Font","Cad","Data","Subtitle","Vector","Model3D","Geo","Text","Mixed","Other"};
 public static readonly string[] Titles={"图片","PDF","文档","表格","演示文稿","视频","音频","压缩包","电子书","字体","CAD","结构化数据","字幕","矢量图","3D 模型","地理数据","纯文本","混合类型","其他文件"};
 public static string[] Default(string category){var all="png webp pdf jpg ico bmp tiff avif docx txt mp3 mp4 zip extract xlsx csv json pptx html mkv mov webm gif wav flac m4a ogg opus aac odt ods odp ttf otf woff woff2 eot dxf dwg svg 7z tar tgz epub mobi azw3 glb gltf obj stl ply 3mf yaml toml xml ass srt vtt lrc geojson kml kmz gpx".Split(' ').Select(f=>new Route(f,"","")).ToArray();return WheelModel.Targets(all,category).Where(f=>f!=WheelModel.More).ToArray();}
 public static List<string[]> Read(Preferences pref,string category){List<string[]> pages;if(pref.WheelLayouts!=null&&pref.WheelLayouts.TryGetValue(category,out pages)&&pages!=null&&pages.Count>0)return pages.Take(8).Select(p=>Enumerable.Range(0,7).Select(i=>p!=null&&i<p.Length?(p[i]??"").Trim().ToLowerInvariant():"").ToArray()).ToList();return new List<string[]>{Default(category)};}
 public static List<string[]> Build(Preferences pref,IEnumerable<Route> routes,string category){var available=routes.Select(r=>r.Format).Distinct().ToArray();var fallback=WheelModel.Targets(routes,category).Where(f=>f!=WheelModel.More).Concat(available).Distinct().ToArray();var used=new HashSet<string>();var result=new List<string[]>();foreach(var page in Read(pref,category)){var selected=page.Where(f=>available.Contains(f)).Distinct().Take(7).ToList();foreach(var f in fallback.Where(f=>!used.Contains(f)).Concat(fallback)){if(selected.Count==7)break;if(!selected.Contains(f))selected.Add(f);}foreach(var f in selected)used.Add(f);result.Add(selected.Concat(new[]{WheelModel.More}).ToArray());}var remaining=fallback.Where(f=>!used.Contains(f)).ToArray();for(int offset=0;offset<remaining.Length;offset+=7)result.Add(remaining.Skip(offset).Take(7).Concat(new[]{WheelModel.More}).ToArray());return result;}
 public static string Category(string[] files){var categories=files.Select(f=>{var detected=Backend.Detect(f);if(detected!=null)return detected.Category;string ext=Converter.Ext(f);return Converter.In(ext,"png jpg jpeg bmp gif webp tif tiff ico avif")?"Image":ext=="pdf"?"Pdf":ext=="txt"?"Text":"Other";}).Distinct().ToArray();return categories.Length==1?categories[0]:"Mixed";}
}
public partial class MainWindow {
 public void WheelPresetEditor(StackPanel page){var section=new StackPanel();section.Children.Add(T("轮盘页面与格式预设",19,"#7EE9D5"));section.Children.Add(T("按文件类型配置，每页 7 个格式，顺时针从顶部排列。“更多格式”固定保留。其余目标自动分页。\n长按右键期间滚动鼠标滚轮翻页，也支持方向键 / PageUp、PageDown。",12,"#8C9BB2",new Thickness(0,8,0,12)));
  var type=new ComboBox(){Name="WheelCategory",ItemsSource=WheelPresets.Titles,SelectedIndex=0,MinWidth=160,Margin=new Thickness(0,0,10,0)};var pagesBox=new ComboBox(){Name="WheelPage",MinWidth=100};var selectors=new WrapPanel();selectors.Children.Add(type);selectors.Children.Add(pagesBox);section.Children.Add(selectors);var slots=new Grid(){Margin=new Thickness(0,12,0,10)};slots.ColumnDefinitions.Add(new ColumnDefinition());slots.ColumnDefinitions.Add(new ColumnDefinition());for(int i=0;i<4;i++)slots.RowDefinitions.Add(new RowDefinition());section.Children.Add(slots);var state=T("",11,"#8C9BB2");var formats=(Backend.Ready?Backend.Catalog.Formats.Select(f=>f.Id=="folder"?"extract":f.Id):"png jpg webp pdf docx txt mp3 mp4 zip extract bmp tiff ico avif csv xlsx".Split(' ')).Concat(new[]{"extract","gz"}).Distinct().OrderBy(f=>f).ToArray();var choices=new[]{"自动补位"}.Concat(formats.Select(f=>f.ToUpperInvariant())).ToArray();var boxes=new ComboBox[7];for(int i=0;i<7;i++){boxes[i]=new ComboBox(){Name="WheelSlot"+(i+1),ItemsSource=choices,IsEditable=true,IsTextSearchEnabled=true,StaysOpenOnEdit=true,MinWidth=170,Margin=new Thickness(0,4,12,0),ToolTip="输入格式或展开选择，例如 PNG、DOCX；自动补位使用当前可用格式"};var field=Field("位置 "+(i+1)+(i==0?" · 顶部":""),boxes[i]);field.Margin=new Thickness(0,0,0,9);Grid.SetRow(field,i/2);Grid.SetColumn(field,i%2);slots.Children.Add(field);}
  string category="Image";var working=WheelPresets.Read(Pref,category);int current=0;bool changing=false;Action store=()=>{working[current]=boxes.Select(b=>b.Text.Trim().Equals("自动补位")?"":b.Text.Trim().ToLowerInvariant()).ToArray();};Action load=()=>{changing=true;pagesBox.ItemsSource=Enumerable.Range(1,working.Count).Select(n=>"第 "+n+" 页").ToArray();pagesBox.SelectedIndex=current;for(int i=0;i<7;i++)boxes[i].Text=String.IsNullOrEmpty(working[current][i])?"自动补位":working[current][i].ToUpperInvariant();changing=false;};
  pagesBox.SelectionChanged+=(s,e)=>{if(changing||pagesBox.SelectedIndex<0)return;store();current=pagesBox.SelectedIndex;load();state.Text="尚未保存；点击下方保存应用全部页面。";};type.SelectionChanged+=(s,e)=>{if(changing||type.SelectedIndex<0)return;category=WheelPresets.Categories[type.SelectedIndex];working=WheelPresets.Read(Pref,category);current=0;load();state.Text="切换类型前，请先保存当前类型的修改。";};
  var controls=new WrapPanel();controls.Children.Add(Btn("新增一页",()=>{if(working.Count>=8){state.Text="每种类型最多 8 页。";return;}store();working.Add(new string[7]);current=working.Count-1;load();}));controls.Children.Add(Btn("删除当前页",()=>{if(working.Count==1){state.Text="至少保留一页；可使用恢复默认。";return;}working.RemoveAt(current);current=Math.Min(current,working.Count-1);load();}));controls.Children.Add(Btn("恢复此类型默认",()=>{working=new List<string[]>{WheelPresets.Default(category)};current=0;load();state.Text="已载入默认，请保存应用。";}));section.Children.Add(controls);section.Children.Add(T("未放入预设的可用格式会自动接到后续页面；无需手动新增才能翻页。\n切换类型前先保存，保存会应用该类型的所有页面。",11,"#8C9BB2",new Thickness(0,10,0,10)));section.Children.Add(Btn("保存该类型的全部轮盘页面",()=>{store();foreach(var values in working){var chosen=values.Where(f=>f!="").ToArray();string bad=chosen.FirstOrDefault(f=>!formats.Contains(f));if(bad!=null){state.Text="无法识别格式："+bad.ToUpperInvariant()+"。请从列表选择。";return;}if(chosen.Distinct().Count()!=chosen.Length){state.Text="同一页不能重复选择格式，请修改后保存。";return;}}if(Pref.WheelLayouts==null)Pref.WheelLayouts=new Dictionary<string,List<string[]>>();Pref.WheelLayouts[category]=working.Select(v=>v.ToArray()).ToList();Pref.Save();state.Text="已保存 · "+WheelPresets.Titles[Array.IndexOf(WheelPresets.Categories,category)]+" · "+working.Count+" 页，下次打开轮盘生效。";},true));section.Children.Add(state);load();page.Children.Add(Card(section,new Thickness(0,18,0,0)));}
}
}
